message.content:
- Failures recur as exhaustive room/container searches, carrying wrong objects, skipping clean/heat/cool, and undoing a completed placement.
- Maintain reusable stages: find_target, take_target, transform, go_destination, put_target, wrong_inventory, plus placed_count/locations for two-object tasks.
- on_init teaches task order; on_post_step updates stage from inventory/world facts; make_pre_hint gives deduped subgoal hints; on_before_action narrowly blocks wrong puts, skipped transforms, and taking back placed targets.
- Avoided regression by not forcing numbered ALFWorld actions and by only blocking when target/destination/placement evidence is clear.
</think>
<patch>{
  "benchmark": "alfworld",
  "description": "Add compact stage tracking with soft guidance and narrow guards for transform and placement order.",
  "actions": [
    {
      "type": "add_code_hook",
      "hook": "on_init",
      "code": "def hook(ctx, nb):
    nb['stage'] = 'find_target'
    nb['last_hint'] = ''
    nb['placed_count'] = 0
    nb['transformed'] = False
    nb['placed_locs'] = []
    return {'skills': [{'text': 'ALFWorld order: find a target, take it, do any required clean heat or cool step, go to the destination, then put it there. For two-object tasks, place two targets at the same destination and do not take back a target already placed.'}], 'tool_hint': 'Do not carry or place a wrong object type; after a successful put, leave the target there.'}"
    },
    {
      "type": "add_code_hook",
      "hook": "on_post_step",
      "code": "def getv(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return default
    return cur

def text(x):
    if x is None:
        return ''
    if isinstance(x, dict):
        return ' '.join([text(v) for v in x.values()]).lower()
    if isinstance(x, list) or isinstance(x, tuple):
        return ' '.join([text(v) for v in x]).lower()
    return str(x).lower()

def hook(ctx, nb):
    task_type = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    world = getv(ctx, 'world', {})
    if not isinstance(world, dict):
        world = {}
    adm = ctx.get('admissible') or []
    inv = text(world.get('inventory', getv(ctx, 'world.inventory', '')))
    inv_nonempty = bool(inv) and 'nothing' not in inv and 'empty' not in inv and 'none' not in inv
    has_target = bool(target and target in inv)
    wrong_inv = bool(inv_nonempty and target and not has_target)
    trans = ''
    if 'clean' in task_type:
        trans = 'clean'
    elif 'heat' in task_type:
        trans = 'heat'
    elif 'cool' in task_type:
        trans = 'cool'
    if trans:
        if target and trans == 'clean' and 'wash' in task_type and 'wash' in inv:
            has_target = True
        if target and trans and 'nothing happens' not in inv and 'not enough' not in inv and 'cannot' not in inv:
            has_target = True
        if target and trans and trans in inv and 'nothing happens' not in inv and 'not enough' not in inv and 'cannot' not in inv:
            has_target = True
        if target and trans and target in inv and trans in inv and 'nothing happens' not in inv and 'not enough' not in inv and 'cannot' not in inv:
            has_target = True
    if trans and target and target in inv:
        if trans in inv and 'nothing happens' not in inv and 'not enough' not in inv and 'cannot' not in inv:
            nb['transformed'] = True
        if trans == 'clean' and 'wash' in inv and 'nothing happens' not in inv and 'not enough' not in inv and 'cannot' not in inv:
            nb['transformed'] = True
        if trans == 'heat' and 'hot' in inv and 'nothing happens' not in inv and 'not enough' not in inv and 'cannot' not in inv:
            nb['transformed'] = True
        if trans == 'cool' and 'cold' in inv and 'nothing happens' not in inv and 'not enough' not in inv and 'cannot' not in inv:
            nb['transformed'] = True
    pc = world.get('placed_count', getv(ctx, 'world.placed_count', nb.get('placed_count', 0)))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = world.get('placed_locations', getv(ctx, 'world.placed_locations', []))
    if isinstance(locs, (list, tuple)) and locs:
        nb['placed_locs'] = [text(x) for x in locs]
    take_ready = False
    put_ready = False
    for a in adm:
        al = text(a)
        if target and al.startswith('take ' + target + ' '):
            take_ready = True
        if target and dest and al.startswith('put ' + target + ' ') and dest in al:
            put_ready = True
    if wrong_inv:
        stage = 'wrong_inventory'
    elif inv_nonempty and has_target and trans and not nb.get('transformed'):
        stage = 'transform'
    elif inv_nonempty and has_target:
        stage = 'put_target' if put_ready else 'go_destination'
    else:
        stage = 'take_target' if take_ready else 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['transform'] = trans
    nb['has_target'] = has_target
    nb['wrong_inventory'] = wrong_inv
    return None"
    },
    {
      "type": "add_code_hook",
      "hook": "make_pre_hint",
      "code": "def getv(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return default
    return cur

def hook(ctx, nb):
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    trans = nb.get('transform') or ''
    stage = nb.get('stage') or ''
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it at the goal; free your hand and search for the required ' + target + '.'
    elif stage == 'transform' and trans:
        msg = 'Before placing the ' + target + ', use the admissible ' + trans + ' action at the proper appliance or sink. A wrong transform or skipping it will cause failure.'
    elif stage == 'put_target' and dest:
        msg = 'You have the prepared ' + target + '. Go to the ' + dest + ' and use the put action there; do not put it on or in a different receptacle.'
    elif stage == 'find_target' and 'two' in (ctx.get('task.task_type') or ''):
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and return to the same ' + dest + '.'
    if not msg:
        return None
    key = stage + ':' + msg[:70]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}"
    },
    {
      "type": "add_code_hook",
      "hook": "on_before_action",
      "code": "def getv(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return default
    return cur

def text(x):
    if x is None:
        return ''
    if isinstance(x, dict):
        return ' '.join([text(v) for v in x.values()]).lower()
    if isinstance(x, list) or isinstance(x, tuple):
        return ' '.join([text(v) for v in x]).lower()
    return str(x).lower()

def hook(ctx, nb):
    action = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    trans = nb.get('transform') or ''
    task_type = text(getv(ctx, 'task.task_type', ''))
    if not target or not action:
        return None
    pc = nb.get('placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    locs = nb.get('placed_locs') or []
    if not isinstance(locs, (list, tuple)):
        locs = []
    placed_here = pc > 0 and dest and (' from ' + dest) in action
    if placed_here or (pc > 0 and target in action and ' from ' in action and any(target in text(x) for x in locs)):
        return {'kind': 'block_and_prompt', 'message': 'Do not take back a target that has already been placed. Leave it there and continue with any remaining required target or final step.'}
    if nb.get('has_target') and trans and not nb.get('transformed') and trans != 'clean' and trans != 'heat' and trans != 'cool':
        if action.startswith('put ' + target + ' '):
            return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First complete the required ' + trans + ' step using the admissible transform action.'}
        if trans == 'clean' and 'wash' in task_type and action.startswith('wash ' + target + ' '):
            return {'kind': 'block_and_prompt', 'message': 'Do not wash the target here. Use the admissible clean action at the proper appliance or sink first.'}
        if trans != 'clean' and action.startswith(trans + ' ' + target + ' '):
            return {'kind': 'block_and_prompt', 'message': 'Do not use the wrong transform action. Use the admissible ' + trans + ' action for this target.'}
    wrong_put = bool(dest and action.startswith('put ' + target + ' ') and dest not in action and nb.get('has_target'))
    if wrong_put and (action in (ctx.get('output') or '') or 'nothing happens' in (ctx.get('observation') or '') or 'not enough' in (ctx.get('observation') or '')):
        return {'kind': 'block_and_prompt', 'message': 'This is not the required destination for the target. Carry it to the ' + dest + ' and put it there.'}
    return None"
    }
